# SG-Advance sensor installer for Windows (M12). Generated by the control plane; the install command
# checks this file's SHA-256 before running it, so do not edit a copy and expect it to run.
#
# What it does, as the signed-in user (no administrator rights needed):
#   1. downloads the sensor wheel, its pinned dependencies list and the device CA, checking each SHA-256
#   2. makes a Python virtual environment under %LOCALAPPDATA%\SG-Advance and installs into it
#      (every dependency must match a pinned hash: pip --require-hashes)
#   3. enrolls this PC: a key is made here and never leaves; the control plane signs a device certificate
#   4. agents on this PC, each checked before every tool call runs:
#      - Claude Code: the SG-Advance hook. From an administrator PowerShell it goes into Claude Code's
#        managed settings (users cannot remove it, bypass mode off); otherwise into the user's settings
#      - OpenClaw: the gateway plugin, and the sensor watches the gateway with its own token (copied, never printed)
#   5. registers the sensor to start at sign-in (Task Scheduler, or the Startup folder if tasks are not allowed)
# Inputs (environment): SGA_ENROLL_TOKEN (required), SGA_DEVICE_ID, SGA_USER.

$ErrorActionPreference = 'Stop'
$ProgressPreference = 'SilentlyContinue'

$LanUrl        = '@@LAN_URL@@'
$InstallUrl    = '@@INSTALL_URL@@'
$CaFingerprint = '@@CA_FINGERPRINT@@'
$CaFileSha256  = '@@CA_FILE_SHA256@@'
$Wheel         = '@@WHEEL@@'
$WheelSha256   = '@@WHEEL_SHA256@@'
$ReqSha256     = '@@REQ_SHA256@@'
$PluginSha256  = '@@PLUGIN_SHA256@@'

$Token = $env:SGA_ENROLL_TOKEN
$DeviceId = if ($env:SGA_DEVICE_ID) { $env:SGA_DEVICE_ID } else { ($env:COMPUTERNAME).ToLower() }
$User = if ($env:SGA_USER) { $env:SGA_USER } else { $env:USERNAME }
$Root = Join-Path $env:LOCALAPPDATA 'SG-Advance'
$SgaHome = Join-Path $env:USERPROFILE '.sg-advance'
$Enrolled = Test-Path (Join-Path $SgaHome 'credentials.json')
if (-not $Enrolled -and -not $Token) {
    throw 'SGA_ENROLL_TOKEN is not set: use the install command you got from the security team.'
}
$Dl = Join-Path $Root 'download'
New-Item -ItemType Directory -Force -Path $Dl | Out-Null

function Get-Pinned([string]$Name, [string]$Sha256) {
    $out = Join-Path $Dl $Name
    Invoke-WebRequest -UseBasicParsing -Uri "$InstallUrl/install/$Name" -OutFile $out
    $got = (Get-FileHash -Algorithm SHA256 -Path $out).Hash.ToLower()
    if ($got -ne $Sha256) {
        Remove-Item -Force $out
        throw "$Name was changed on the way: SHA-256 $got, expected $Sha256"
    }
    return $out
}

Write-Host '[1/5] downloading and checking the sensor'
$Ca  = Get-Pinned 'ca.pem' $CaFileSha256
$Req = Get-Pinned 'requirements.txt' $ReqSha256
$Whl = Get-Pinned $Wheel $WheelSha256

Write-Host '[2/5] installing into a private Python environment'
$Py = $null
foreach ($cand in @('py -3.13', 'py -3.12', 'python', 'python3')) {
    $parts = $cand.Split(' ')
    $exe = $parts[0]
    $pyArgs = @($parts | Select-Object -Skip 1)
    if (-not (Get-Command $exe -ErrorAction SilentlyContinue)) { continue }
    try {
        $ok = & $exe @pyArgs -c 'import sys; print(sys.version_info >= (3, 12))' 2>$null
    } catch { $ok = $null }
    if ($ok -eq 'True') { $Py = @($exe) + $pyArgs; break }
}
if (-not $Py) { throw 'Python 3.12 or newer is needed (python.org, or: winget install Python.Python.3.12).' }
$Venv = Join-Path $Root 'venv'
$VPy = Join-Path $Venv 'Scripts\python.exe'
if (-not (Test-Path $VPy)) {
    $pyExe = $Py[0]
    $pyRest = @($Py | Select-Object -Skip 1)
    & $pyExe @pyRest -m venv $Venv
    if ($LASTEXITCODE) { throw 'could not create the virtual environment' }
}
& $VPy -m pip install --disable-pip-version-check --quiet --require-hashes --only-binary=:all: -r $Req
if ($LASTEXITCODE) { throw 'installing the pinned dependencies failed' }
& $VPy -m pip install --disable-pip-version-check --quiet --no-deps --force-reinstall $Whl
if ($LASTEXITCODE) { throw 'installing the sensor failed' }
$Sga = Join-Path $Venv 'Scripts\sga-sensor.exe'

Write-Host "[3/5] enrolling this PC as $DeviceId"
if ($Enrolled) {
    Write-Host '      already enrolled: keeping the existing identity (re-running updates the sensor and plugin)'
} else {
    & $Sga --home $SgaHome enroll --server $LanUrl --token $Token --device-id $DeviceId --ca-file $Ca --ca-sha256 $CaFingerprint
    if ($LASTEXITCODE) { throw 'enrollment failed (token used or expired? ask for a new install command)' }
}
Remove-Item Env:SGA_ENROLL_TOKEN -ErrorAction SilentlyContinue
$Token = $null

Write-Host '[4/5] AI agents on this PC'
$RunArgs = @('--user', $User)
$IsAdmin = ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole(
    [Security.Principal.WindowsBuiltInRole]::Administrator)
if (Get-Command claude -ErrorAction SilentlyContinue) {
    $ccArgs = @('--home', $SgaHome, 'claude-code', 'install', '--user', $User)
    if ($IsAdmin) { $ccArgs += '--managed' }
    & $Sga @ccArgs
    if ($LASTEXITCODE) { throw 'putting the SG-Advance hook into Claude Code failed' }
    if (-not $IsAdmin) { Write-Host '      (not administrator: the user can remove this hook; the sensor reports it if they do)' }
} else {
    Write-Host '      Claude Code is not installed: the sensor will still notice if it appears'
}
$OcConfig = Join-Path $env:USERPROFILE '.openclaw\openclaw.json'
$Oc = Get-Command openclaw -ErrorAction SilentlyContinue
if ($Oc -and $PluginSha256) {
    $Zip = Get-Pinned 'sg-advance-plugin.zip' $PluginSha256
    $PluginDir = Join-Path $Root 'openclaw-plugin'
    if (Test-Path $PluginDir) { Remove-Item -Recurse -Force $PluginDir }
    Expand-Archive -Path $Zip -DestinationPath $PluginDir
    & openclaw plugins install --link $PluginDir --force --accept-capabilities
    if ($LASTEXITCODE) { throw 'installing the SG-Advance OpenClaw plugin failed' }
    & openclaw config set plugins.entries.sg-advance.enabled true
    & openclaw config set plugins.entries.sg-advance.config.sensorCli $Sga
    Write-Host '      plugin installed: every tool call is checked by the sensor before it runs'
    $Port = 18789
    $GwToken = $null
    if (Test-Path $OcConfig) {
        $cfg = Get-Content -Raw $OcConfig | ConvertFrom-Json
        if ($cfg.gateway.port) { $Port = [int]$cfg.gateway.port }
        if ($cfg.gateway.auth.token) { $GwToken = [string]$cfg.gateway.auth.token }
    }
    if ($GwToken) {
        Set-Content -NoNewline -Encoding ascii -Path (Join-Path $SgaHome 'openclaw-token') -Value $GwToken
        $GwToken = $null
        $RunArgs += @('--openclaw', "ws://127.0.0.1:$Port")
        Write-Host "      the sensor will watch the gateway on port $Port"
    } else {
        Write-Host '      no gateway token in openclaw.json: the plugin works, gateway watching is off'
    }
    & openclaw gateway restart 2>$null
    if ($LASTEXITCODE) { Write-Host '      restart OpenClaw yourself so it loads the plugin' }
} elseif ($Oc) {
    Write-Host '      OpenClaw found, but this control plane serves no plugin: install it later'
} else {
    Write-Host '      OpenClaw is not installed: the sensor will still notice if it appears'
}

Write-Host '[5/5] starting the sensor at sign-in'
& $Sga --home $SgaHome service install @RunArgs
if ($LASTEXITCODE) { throw 'registering the sensor to start at sign-in failed' }
& $Sga --home $SgaHome status
Write-Host ''
Write-Host "Done. Log: $SgaHome\logs\sensor.log   Remove: $Sga --home $SgaHome service uninstall"
